"use client";

import { useState } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  ArrowRight,
  Search,
  Phone,
  MessageCircle,
  Check,
  Building2,
  Home,
  Building,
  Layers,
  Castle,
  Hotel,
  DoorOpen,
  Trees,
  type LucideIcon,
} from "lucide-react";
import { buttonVariants } from "@/components/ui/Button";
import { toast } from "@/lib/toast";
import { cn } from "@/lib/utils";

const PROPERTY_TYPES: { label: string; icon: LucideIcon }[] = [
  { label: "Apartment", icon: Building2 },
  { label: "Independent House", icon: Home },
  { label: "Duplex", icon: Building },
  { label: "Independent Floor", icon: Layers },
  { label: "Villa", icon: Castle },
  { label: "Penthouse", icon: Hotel },
  { label: "Studio", icon: DoorOpen },
  { label: "Farm House", icon: Trees },
];

const STEPS = ["Property Details", "Price Details"] as const;

const UNDERLINE_FIELD =
  "w-full rounded-none border-0 border-b border-border bg-transparent px-0 py-2 text-base text-foreground outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-brand-navy";

type FormState = {
  name: string;
  city: string;
  propertyType: string | null;
  expectedPrice: string;
  maintenance: string;
  tokenAmount: string;
  negotiable: boolean;
  allInclusive: boolean;
};

const initialForm: FormState = {
  name: "",
  city: "",
  propertyType: null,
  expectedPrice: "",
  maintenance: "",
  tokenAmount: "",
  negotiable: false,
  allInclusive: false,
};

export default function PostPropertyPage() {
  const [step, setStep] = useState(0);
  const [form, setForm] = useState<FormState>(initialForm);

  function set<K extends keyof FormState>(key: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }

  const progress = step === 0 ? 5 : 55;

  function next() {
    if (step === 0) {
      if (!form.name.trim()) return toast("Enter your name to continue.", "error");
      if (!form.city.trim()) return toast("Search and pick a city to continue.", "error");
      if (!form.propertyType) return toast("Choose a property type to continue.", "error");
      setStep(1);
      return;
    }
    if (!form.expectedPrice.trim()) return toast("Enter an expected price to continue.", "error");
    toast("Property details saved!");
  }

  function back() {
    if (step === 0) return;
    setStep(0);
  }

  function railState(i: number): "done" | "active" | "pending" {
    if (i < step) return "done";
    if (i === step) return "active";
    return "pending";
  }

  return (
    <div className="container-rentlet py-6 pb-24">
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-[300px_1fr]">
        {/* Left rail */}
        <aside className="lg:sticky lg:top-24 lg:h-fit">
          <Link
            href="/"
            className="inline-flex items-center gap-1.5 text-sm font-semibold text-muted-foreground hover:text-foreground"
          >
            <ArrowLeft className="h-4 w-4" /> Go back
          </Link>

          <h1 className="mt-4 text-2xl font-extrabold text-foreground">Post your property</h1>
          <p className="mt-1 text-sm text-muted-foreground">Sell or rent your property</p>

          <div className="mt-4">
            <div className="h-1.5 w-full overflow-hidden rounded-full bg-muted">
              <div
                className="h-full rounded-full bg-brand-orange transition-all"
                style={{ width: `${progress}%` }}
              />
            </div>
            <p className="mt-1 text-right text-xs font-semibold text-muted-foreground">{progress}%</p>
          </div>

          <ol className="mt-6 flex flex-col">
            {STEPS.map((label, i) => {
              const st = railState(i);
              const last = i === STEPS.length - 1;
              return (
                <li key={label} className="flex gap-3">
                  <div className="flex flex-col items-center">
                    <button
                      type="button"
                      onClick={() => st === "done" && setStep(i)}
                      disabled={st !== "done"}
                      className={cn(
                        "flex h-7 w-7 shrink-0 items-center justify-center rounded-full border-2",
                        st === "done" && "border-brand-navy bg-brand-navy text-white",
                        st === "active" && "border-brand-navy bg-brand-navy",
                        st === "pending" && "border-border bg-white"
                      )}
                    >
                      {st === "done" ? (
                        <Check className="h-3.5 w-3.5" />
                      ) : (
                        <span
                          className={cn(
                            "h-2.5 w-2.5 rounded-full",
                            st === "active" ? "bg-white" : "bg-border"
                          )}
                        />
                      )}
                    </button>
                    {!last && <span className="my-1 w-0.5 flex-1 bg-border" />}
                  </div>
                  <div className={cn("flex flex-col", !last && "pb-8")}>
                    <span
                      className={cn(
                        "text-sm font-bold",
                        st === "pending" ? "text-muted-foreground" : "text-foreground"
                      )}
                    >
                      {label}
                    </span>
                    <span
                      className={cn(
                        "mt-1 w-fit rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide",
                        st === "done" && "bg-emerald-50 text-emerald-700",
                        st === "active" && "bg-brand-navy-light text-brand-navy",
                        st === "pending" && "bg-muted text-muted-foreground"
                      )}
                    >
                      {st === "done" ? "Done" : st === "active" ? "In progress" : "Pending"}
                    </span>
                  </div>
                </li>
              );
            })}
          </ol>

          <div className="mt-4 rounded-xl bg-muted/50 p-3 text-xs leading-relaxed text-muted-foreground">
            <span className="font-semibold text-foreground">Need help?</span> Now you can directly post
            property via{" "}
            <a
              href={`https://wa.me/?text=${encodeURIComponent("Hi Rentlet, I'd like to post my property.")}`}
              target="_blank"
              rel="noreferrer"
              className="inline-flex items-center gap-1 font-semibold text-emerald-600 hover:underline"
            >
              <MessageCircle className="h-3.5 w-3.5" /> WhatsApp
            </a>
          </div>
        </aside>

        {/* Main panel */}
        <div className="min-w-0 rounded-2xl border border-border bg-white p-5 sm:p-8">
          {/* Timer banner */}
          <div className="flex items-center gap-3 rounded-xl bg-brand-orange-light/50 px-4 py-3 text-sm text-foreground">
            <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-white text-brand-orange">
              <Phone className="h-4 w-4" />
            </span>
            <p>
              Timer&apos;s up! but you will <span className="font-bold">still get 3 free</span> enquiries.{" "}
              <span className="font-bold">Just finish posting!</span>
            </p>
          </div>

          <div className="mt-6 flex items-start justify-between gap-4">
            <h2 className="text-xl font-extrabold text-foreground">
              {step === 0 ? "Add Property Details" : "Add Price Details"}
            </h2>
            <button
              type="button"
              className="inline-flex shrink-0 items-center gap-1.5 text-sm font-semibold text-brand-navy hover:underline"
            >
              <span className="text-muted-foreground">Need help?</span>
              <Phone className="h-4 w-4" /> Get a callback
            </button>
          </div>

          {step === 0 ? (
            <div className="mt-6 max-w-2xl space-y-8">
              {/* Your Name */}
              <label className="block">
                <span className="text-sm text-muted-foreground">Your Name</span>
                <input
                  type="text"
                  value={form.name}
                  onChange={(e) => set("name", e.target.value)}
                  placeholder="Enter your name"
                  className={cn(UNDERLINE_FIELD, "mt-1")}
                />
              </label>

              {/* City */}
              <label className="block">
                <span className="text-sm text-muted-foreground">City</span>
                <span className="mt-1 flex items-center gap-2 border-b border-border focus-within:border-brand-navy">
                  <Search className="h-4 w-4 shrink-0 text-muted-foreground" />
                  <input
                    type="text"
                    value={form.city}
                    onChange={(e) => set("city", e.target.value)}
                    placeholder="Search City"
                    className="w-full border-0 bg-transparent py-2 text-base text-foreground outline-none placeholder:text-muted-foreground/70"
                  />
                </span>
              </label>

              {/* Property Type */}
              <div>
                <p className="text-sm text-muted-foreground">Property Type</p>
                <div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5">
                  {PROPERTY_TYPES.map((t) => {
                    const active = form.propertyType === t.label;
                    return (
                      <button
                        key={t.label}
                        type="button"
                        onClick={() => set("propertyType", t.label)}
                        className={cn(
                          "flex flex-col items-center gap-2 rounded-xl border p-4 text-center transition-colors",
                          active
                            ? "border-brand-navy bg-brand-navy-light/40"
                            : "border-border hover:border-brand-navy"
                        )}
                      >
                        <t.icon
                          className={cn(
                            "h-7 w-7",
                            active ? "text-brand-navy" : "text-muted-foreground"
                          )}
                          strokeWidth={1.5}
                        />
                        <span className="text-xs font-semibold text-foreground">{t.label}</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
          ) : (
            <div className="mt-6 max-w-2xl space-y-8">
              {/* Expected price */}
              <label className="block">
                <span className="text-sm text-muted-foreground">Expected Price</span>
                <span className="mt-1 flex items-center gap-2 border-b border-border focus-within:border-brand-navy">
                  <span className="text-base font-semibold text-muted-foreground">₹</span>
                  <input
                    type="text"
                    inputMode="numeric"
                    value={form.expectedPrice}
                    onChange={(e) => set("expectedPrice", e.target.value.replace(/[^\d]/g, ""))}
                    placeholder="Enter amount"
                    className="w-full border-0 bg-transparent py-2 text-base text-foreground outline-none placeholder:text-muted-foreground/70"
                  />
                </span>
              </label>

              {/* Maintenance */}
              <label className="block">
                <span className="text-sm text-muted-foreground">Maintenance (monthly)</span>
                <span className="mt-1 flex items-center gap-2 border-b border-border focus-within:border-brand-navy">
                  <span className="text-base font-semibold text-muted-foreground">₹</span>
                  <input
                    type="text"
                    inputMode="numeric"
                    value={form.maintenance}
                    onChange={(e) => set("maintenance", e.target.value.replace(/[^\d]/g, ""))}
                    placeholder="Optional"
                    className="w-full border-0 bg-transparent py-2 text-base text-foreground outline-none placeholder:text-muted-foreground/70"
                  />
                </span>
              </label>

              {/* Token amount */}
              <label className="block">
                <span className="text-sm text-muted-foreground">Booking / Token amount</span>
                <span className="mt-1 flex items-center gap-2 border-b border-border focus-within:border-brand-navy">
                  <span className="text-base font-semibold text-muted-foreground">₹</span>
                  <input
                    type="text"
                    inputMode="numeric"
                    value={form.tokenAmount}
                    onChange={(e) => set("tokenAmount", e.target.value.replace(/[^\d]/g, ""))}
                    placeholder="Optional"
                    className="w-full border-0 bg-transparent py-2 text-base text-foreground outline-none placeholder:text-muted-foreground/70"
                  />
                </span>
              </label>

              <div className="space-y-3">
                <label className="flex items-center gap-2.5 text-sm text-foreground">
                  <input
                    type="checkbox"
                    checked={form.negotiable}
                    onChange={(e) => set("negotiable", e.target.checked)}
                    className="h-4 w-4 rounded border-border accent-brand-navy"
                  />
                  Price negotiable
                </label>
                <label className="flex items-center gap-2.5 text-sm text-foreground">
                  <input
                    type="checkbox"
                    checked={form.allInclusive}
                    onChange={(e) => set("allInclusive", e.target.checked)}
                    className="h-4 w-4 rounded border-border accent-brand-navy"
                  />
                  All-inclusive price
                </label>
              </div>
            </div>
          )}

          {/* Nav */}
          <div className="mt-8 flex items-center justify-between gap-3 border-t border-border pt-5">
            <button
              type="button"
              onClick={back}
              className={cn(buttonVariants({ variant: "outline", size: "md" }), step === 0 && "invisible")}
            >
              <ArrowLeft className="h-4 w-4" /> Back
            </button>
            <button
              type="button"
              onClick={next}
              className={cn(buttonVariants({ variant: "primary", size: "lg" }))}
            >
              {step === 0 ? "Continue" : "Save details"}
              <ArrowRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
